
.panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.block-title {
  font-size: 12px;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 3px;
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.rep-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.rep {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
}

.rep-name {
  width: 5.5em;
  color: var(--c-text);
  opacity: 0.85;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rep-bar {
  flex: 1;
  height: 8px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 1px;
  overflow: hidden;
}

.rep-fill {
  height: 100%;
  transition: width 0.4s ease;
  background: currentColor;
}

.rep-val {
  width: 3em;
  text-align: right;
  font-weight: bold;
}

.rep-tier {
  width: 5em;
  font-size: 11px;
  opacity: 0.85;
}

.tier-high {
  color: #4cd964;
}

.tier-mid {
  color: var(--c-primary);
}

.tier-normal {
  color: var(--c-warn);
}

.tier-low {
  color: #b48cff;
}

.tier-zero {
  color: var(--c-border);
}

.empty-hint {
  font-size: 12px;
  color: var(--c-border);
}
