
.panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.block-title {
  font-size: 12px;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 3px;
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.quest-detail {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.quest-row {
  display: flex;
  font-size: 12px;

  .label {
    width: 4em;
    color: var(--c-text);
    opacity: 0.7;
  }

  .value {
    font-weight: bold;
  }

  .stage {
    color: var(--c-warn);
  }

  .money {
    color: var(--c-warn);
  }

  .reward-list {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    font-weight: normal;
  }

  .reward-chip {
    font-style: normal;
    font-size: 11px;
    color: var(--c-text);
    opacity: 0.9;
    background-color: var(--c-surface);
    border: 1px solid var(--c-border);
    border-radius: 3px;
    padding: 1px 6px;
    white-space: nowrap;

    &.build {
      color: var(--c-primary);
      border-color: var(--c-primary);
    }

    &.inf {
      color: #b48cff;
      border-color: #b48cff;
    }
  }

  .diff-hard {
    color: #ff7a7a;
  }

  .diff-extreme {
    color: var(--c-accent);
  }

  .goal .value {
    font-weight: normal;
    opacity: 0.9;
    line-height: 1.5;
  }
}

.progress-wrap {
  margin-top: 4px;
}

.progress-head {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;

  .progress-num {
    color: var(--c-primary);
    font-weight: bold;
  }
}

.progress-bar {
  margin-top: 4px;
  height: 6px;
  border-radius: 3px;
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  border-radius: 3px;
  background-color: var(--c-primary);
  transition: width 0.25s ease;
}

.event-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.event {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  padding: 3px 0;
  border-bottom: 1px dashed var(--c-border);

  .event-name {
    font-weight: bold;
  }

  .event-state {
    color: var(--c-primary);
    font-size: 11px;
  }
}

.sys-row {
  display: flex;
  gap: 16px;
  font-size: 12px;
  color: var(--c-text);
  opacity: 0.85;
  flex-wrap: wrap;

  i {
    margin-right: 4px;
    color: var(--c-primary);
  }
}

.empty-hint {
  font-size: 12px;
  color: var(--c-border);
}
