
.panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.block-title {
  font-size: 12px;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 3px;
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.attr-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px 14px;
}

.attr {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.attr-name {
  width: 2em;
  color: var(--c-text);
  opacity: 0.8;
}

.bar {
  flex: 1;
  height: 6px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 1px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: var(--c-primary);
  transition: width 0.3s ease;
}

.attr-val {
  width: auto;
  min-width: 2.2em;
  text-align: right;
  color: var(--c-primary);
  font-weight: bold;
  white-space: nowrap;

  em {
    font-style: normal;
    color: #4cd964;
    margin-left: 1px;
  }
}

.attr {
  cursor: help;
}

.cyber-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.cyber-slot {
  padding: 5px 6px;
  border: 1px solid var(--c-border);
  border-radius: 2px;
  font-size: 11px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  color: var(--c-text);

  .slot-name {
    opacity: 0.75;
  }

  .slot-type {
    font-size: 10px;
    font-weight: bold;
  }

  .type-tech {
    color: var(--c-primary);
  }

  .type-magic {
    color: #b48cff;
  }

  .slot-empty {
    font-size: 10px;
    color: var(--c-border);
  }

  &.installed {
    border-color: var(--c-primary);
  }
}

.item-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.item {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  padding: 3px 0;
  border-bottom: 1px dashed var(--c-border);

  em {
    font-style: normal;
    color: var(--c-warn);
    margin-left: 3px;
  }

  .item-name {
    font-weight: bold;
  }

  .item-desc {
    color: var(--c-text);
    opacity: 0.7;
  }
}

.empty-hint {
  font-size: 12px;
  color: var(--c-border);
}

.weapon-equipped {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  margin-bottom: 8px;
}

.equip-label {
  color: var(--c-text);
  opacity: 0.8;
}

.equipped-item {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;

  .item-name {
    font-weight: bold;
    color: var(--c-warn);
  }
}

.weapon-bonus {
  font-size: 11px;
  color: var(--c-primary);
}

.unequip-btn,
.equip-btn {
  padding: 2px 8px;
  font-size: 10px;
  background: transparent;
  border: 1px solid var(--c-accent);
  color: var(--c-accent);
  border-radius: 3px;
  cursor: pointer;

  &:hover {
    background-color: rgba(255, 77, 77, 0.12);
  }
}

.equip-btn.equipping {
  opacity: 0.6;
  cursor: default;
}

.weapon-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.weapon-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  padding: 4px 6px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-surface);

  .weapon-name {
    font-weight: bold;
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .weapon-type {
    color: var(--c-text);
    opacity: 0.7;
    font-size: 11px;
  }

  .weapon-bonus {
    white-space: nowrap;
  }
}

.weapon-mod {
  font-style: normal;
  font-size: 10px;
  color: #ff6b9d;
  border: 1px solid #ff6b9d;
  border-radius: 2px;
  padding: 0 4px;
  margin-left: 3px;
  vertical-align: 1px;
}

.asset-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.asset {
  padding: 6px 8px;
  border: 1px solid var(--c-border);
  border-radius: 3px;
  background-color: var(--c-surface);
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.asset-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;

  &.sub {
    color: var(--c-text);
    opacity: 0.75;
    font-size: 11px;
  }
}

.asset-name {
  font-weight: bold;
  color: var(--c-text);
}

.asset-type {
  font-size: 10px;
  color: var(--c-primary);
  border: 1px solid var(--c-primary);
  border-radius: 2px;
  padding: 0 5px;
}

.asset-state {
  font-size: 10px;
  padding: 0 5px;
  border-radius: 2px;
  font-weight: bold;
}

.state-rent,
.state-own {
  color: var(--c-warn);
  border: 1px solid var(--c-warn);
}

.state-ok {
  color: #4cd964;
  border: 1px solid #4cd964;
}

.state-broken {
  color: var(--c-accent);
  border: 1px solid var(--c-accent);
}

.asset-price {
  color: var(--c-warn);
}

.asset-special {
  color: var(--c-primary);
}

.asset-bonus {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 2px;
}

.bonus-chip {
  font-size: 10px;
  color: var(--c-text);
  background-color: var(--c-background);
  border: 1px solid var(--c-border);
  padding: 0 5px;
  border-radius: 2px;

  em {
    font-style: normal;
    color: #4cd964;
    margin-left: 2px;
  }
}

.asset-trigger {
  font-size: 10px;
  color: var(--c-warn);
  margin-top: 2px;
}

@media (max-width: 560px) {
  .attr-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .cyber-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .item {
    flex-direction: column;
  }
}
