
.store-overlay {
  position: fixed;
  inset: 0;
  background: rgba(4, 6, 10, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 99;
  padding: 16px;
}

.store-panel {
  width: min(560px, 95vw);
  max-height: 86vh;
  overflow-y: auto;
  background-color: var(--c-background);
  border: 2px solid var(--c-primary);
  border-radius: 8px;
  box-shadow: 0 0 24px rgba(0, 229, 255, 0.35);
}

.store-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 14px;
  background-color: var(--c-surface);
  border-bottom: 1px solid var(--c-border);
}

.store-title {
  font-size: 14px;
  color: var(--c-primary);
  margin-bottom: 2px;

  i {
    margin-right: 5px;
  }
}

.store-venue {
  font-size: 11px;
  color: var(--c-text);
  opacity: 0.8;

  em {
    font-style: normal;
    color: var(--c-warn);
  }
}

.close-btn {
  background: transparent;
  border: 1px solid var(--c-border);
  color: var(--c-text);
  width: 26px;
  height: 26px;
  border-radius: 4px;
  cursor: pointer;

  &:hover {
    border-color: var(--c-accent);
    color: var(--c-accent);
  }
}

.venue-pick {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 8px;
  font-size: 12px;
}

.pick-label {
  color: var(--c-primary);
  font-weight: bold;
}

.pick-select {
  background-color: var(--c-surface);
  color: var(--c-text);
  border: 1px solid var(--c-border);
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 12px;
  font-family: inherit;
  max-width: 260px;

  &:focus {
    border-color: var(--c-primary);
    outline: none;
  }
}

.opt-group {
  color: var(--c-text);
  opacity: 0.6;
  font-weight: bold;
  font-size: 11px;
  padding-left: 4px;
}

.venue-hint {
  color: var(--c-primary);
  font-size: 11px;
  opacity: 0.85;

  i {
    margin-right: 3px;
  }
}

.store-note {
  font-size: 12px;
  color: var(--c-text);
  opacity: 0.75;
  padding: 12px 4px;
  text-align: center;
}

.venue-tip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: var(--c-border);
  margin-bottom: 8px;
}

.refresh-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  font-size: 11px;
  color: var(--c-primary);
  background-color: rgba(0, 229, 255, 0.08);
  border: 1px solid var(--c-primary);
  border-radius: 12px;
  cursor: pointer;
  white-space: nowrap;

  &:hover {
    background-color: rgba(0, 229, 255, 0.18);
  }
}

.cart-body {
  padding: 12px 14px;
}

.feedback {
  font-size: 12px;
  padding: 6px 10px;
  border-radius: 4px;
  margin-bottom: 10px;
}

.fb-ok {
  color: #4cd964;
  background-color: rgba(76, 217, 100, 0.1);
}

.fb-red {
  color: var(--c-accent);
  background-color: rgba(255, 77, 77, 0.1);
}

.shop-kinds {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}

.kind-btn {
  padding: 4px 12px;
  font-size: 12px;
  background: transparent;
  border: 1px solid var(--c-border);
  color: var(--c-text);
  border-radius: 14px;
  cursor: pointer;

  &.active {
    border-color: var(--c-primary);
    color: var(--c-primary);
    background-color: rgba(0, 229, 255, 0.08);
  }
}

.goods {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 4px;
  border-bottom: 1px dotted var(--c-border);

  &:last-child {
    border-bottom: none;
  }

  &.sold_out {
    opacity: 0.5;
  }
}

.goods-main {
  flex: 1;
  min-width: 0;
}

.goods-name {
  display: block;
  font-size: 13px;
  color: var(--c-text);
  font-weight: bold;
}

.goods-desc {
  display: block;
  font-size: 11px;
  color: var(--c-text);
  opacity: 0.7;
  margin-top: 2px;
}

.weapon-tag {
  display: inline-block;
  font-size: 10px;
  font-weight: bold;
  padding: 0 5px;
  border-radius: 2px;
  margin-right: 3px;
  vertical-align: 1px;

  &.tag-tech {
    color: var(--c-primary);
    border: 1px solid var(--c-primary);
  }

  &.tag-magic {
    color: #b48cff;
    border: 1px solid #b48cff;
  }

  &.tag-attack {
    color: #ff6b9d;
    border: 1px solid #ff6b9d;
  }
}

.goods-side {
  display: flex;
  align-items: center;
  gap: 8px;
  white-space: nowrap;
}

.goods-gate i {
  width: 1em;
}

.gate-open {
  color: #4cd964;
}

.gate-lock {
  color: var(--c-accent);
}

.goods-price {
  color: var(--c-warn);
  font-size: 12px;

  em {
    font-style: normal;
    color: var(--c-accent);
    font-size: 10px;
    margin-left: 2px;
  }
}

.goods-owned {
  color: var(--c-border);
  font-size: 11px;
}

.goods-held {
  color: var(--c-warn);
  font-size: 11px;
  background-color: rgba(255, 215, 0, 0.1);
  padding: 1px 4px;
  border-radius: 3px;
}

.buy-btn {
  padding: 4px 12px;
  font-size: 12px;
  background-color: var(--c-primary);
  color: #04121a;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-weight: bold;

  &:disabled {
    background-color: var(--c-border);
    color: var(--c-text);
    cursor: not-allowed;
  }

  &.buy-implant {
    background-color: #b48cff;
  }
}
