
.statusbar-root {
  width: 100%;
  font-family: var(--font-sys);
}

.receipt-bar {
  width: 100%;
  max-width: 760px;
  margin: 0 auto 4px;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 6px 10px;
  font-size: 12px;
  line-height: 1.35;
  color: var(--c-primary);
  background-color: rgba(0, 229, 255, 0.07);
  border: 1px solid var(--c-primary);
  border-radius: 4px;

  > i {
    flex-shrink: 0;
  }

  .receipt-text {
    flex: 1;
    min-width: 0;
    white-space: pre-line;
    word-break: break-word;
    max-height: 132px;
    overflow-y: auto;
  }

  .receipt-copy {
    flex-shrink: 0;
    background: transparent;
    border: 1px solid var(--c-primary);
    color: var(--c-primary);
    border-radius: 3px;
    padding: 2px 8px;
    font-size: 11px;
    font-family: inherit;
    cursor: pointer;

    &:hover {
      background-color: var(--c-primary);
      color: var(--c-background);
    }
  }

  .receipt-clear {
    flex-shrink: 0;
    background: transparent;
    border: 1px solid var(--c-border);
    color: var(--c-text);
    border-radius: 3px;
    width: 22px;
    height: 22px;
    line-height: 1;
    font-size: 11px;
    font-family: inherit;
    cursor: pointer;

    &:hover {
      border-color: #4cd964;
      color: #4cd964;
      background-color: rgba(76, 217, 100, 0.1);
    }
  }
}

.statusbar {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  font-family: var(--font-sys);
  font-size: 13px;
  line-height: 1.4;
  color: var(--c-text);
  background-color: var(--c-background);
  border: 2px solid var(--c-border);
  border-radius: 6px;
  overflow: hidden;
  transition: box-shadow 0.3s ease, border-color 0.3s ease;

  &.danger-border {
    border-color: var(--c-accent);
    box-shadow: 0 0 8px rgba(255, 77, 77, 0.4);
    animation: danger-flicker 1.6s ease-in-out infinite;
  }
}

@keyframes danger-flicker {
  0%,
  100% {
    box-shadow: 0 0 6px rgba(255, 77, 77, 0.3);
  }
  50% {
    box-shadow: 0 0 12px rgba(255, 77, 77, 0.55);
  }
}

.titlebar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background-color: var(--c-surface);
  border-bottom: 1px solid var(--c-border);
  flex-wrap: wrap;
}

.meta-left,
.meta-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.loc {
  color: var(--c-primary);
  font-weight: bold;
}

.time {
  color: var(--c-text);
  opacity: 0.85;
}

.money {
  color: var(--c-warn);
}

.quest-badge {
  color: var(--c-warn);
  border: 1px solid var(--c-warn);
  padding: 1px 8px;
  border-radius: 3px;
  font-size: 12px;

  &.active {
    animation: quest-pulse 1.6s ease-in-out infinite;
  }
}

@keyframes quest-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.45;
  }
}

.injury-light {
  color: var(--c-warn);
}

.store-badge {
  position: relative;
  background: transparent;
  border: 1px solid var(--c-border);
  color: var(--c-primary);
  width: 28px;
  height: 28px;
  border-radius: 4px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;

  &:hover {
    border-color: var(--c-primary);
    background-color: rgba(0, 229, 255, 0.08);
  }
}

.store-dot {
  position: absolute;
  top: -3px;
  right: -3px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: #4cd964;
  border: 1px solid var(--c-background);
}

.injury-moderate,
.injury-heavy {
  color: var(--c-accent);
  font-weight: bold;
}

.tabs {
  display: flex;
  gap: 2px;
  border-bottom: 1px solid var(--c-border);
  padding: 0 4px;
  background-color: var(--c-background);

  .tab {
    flex: 1;
    padding: 8px 0;
    background: transparent;
    border: none;
    border-bottom: 2px solid transparent;
    color: var(--c-border);
    cursor: pointer;
    font-family: inherit;
    font-size: 13px;
    transition: color 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;

    i {
      margin-right: 4px;
    }

    &:hover {
      color: var(--c-text);
      background-color: var(--c-surface);
    }

    &.active {
      color: var(--c-primary);
      border-bottom-color: var(--c-primary);
      font-weight: bold;
      text-shadow: 0 0 8px rgba(0, 229, 255, 0.4);
    }
  }
}

.content-area {
  padding: 12px;
  min-height: 0;
}

.panel-fade-enter-active,
.panel-fade-leave-active {
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.panel-fade-enter-from {
  opacity: 0;
  transform: translateY(6px);
}

.panel-fade-leave-to {
  opacity: 0;
  transform: translateY(-6px);
}
