
.panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.block-title {
  font-size: 12px;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 3px;
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.venue-group {
  margin-bottom: 8px;

  &:last-child {
    margin-bottom: 0;
  }
}

.group-label {
  font-size: 11px;
  color: var(--c-text);
  opacity: 0.7;
  margin: 2px 0 4px;
}

.venue {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1.05fr) minmax(0, 0.8fr) minmax(0, 1.8fr);
  align-items: baseline;
  gap: 8px;
  font-size: 12px;
  padding: 3px 0;
  border-bottom: 1px dotted var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.venue-name {
  color: var(--c-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.venue-loc {
  color: var(--c-text);
  opacity: 0.7;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.venue-price {
  color: var(--c-warn);
  text-align: right;
  white-space: nowrap;
}

.venue-gate {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: baseline;
  column-gap: 4px;
  row-gap: 2px;
  white-space: normal;
  min-width: 0;
  font-size: 11px;

  i {
    width: 1em;
    align-self: center;
  }
}

.gate-open {
  color: #4cd964;
}

.gate-lock {
  color: var(--c-accent);
}

.gate-note {
  font-style: normal;
  color: var(--c-text);
  opacity: 0.65;
  font-size: 10px;
  margin-left: 2px;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
  min-width: 0;
}

.empty-hint {
  font-size: 12px;
  color: var(--c-border);
}
