
.npc-panel {
  width: 100%;
  max-width: 760px;
  margin: 0 auto 12px;
  font-family: var(--font-sys);
  font-size: 13px;
  line-height: 1.4;
  color: var(--c-text);
  background: linear-gradient(160deg, var(--c-surface), var(--c-background));
  border: 2px solid var(--c-border);
  border-radius: 6px;
  overflow: hidden;
}

.npc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  cursor: pointer;
  user-select: none;
  border-bottom: 1px solid var(--c-border);

  &:hover {
    background: var(--c-surface);
  }
}

.npc-header-left {
  display: flex;
  align-items: center;
  gap: 8px;

  i.fa-comments {
    color: var(--c-primary);
  }
}

.npc-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-border);
  transition: background 0.3s ease, box-shadow 0.3s ease;

  &.live {
    background: var(--c-primary);
    box-shadow: 0 0 6px rgba(0, 229, 255, 0.8);
  }
}

.npc-title {
  color: var(--c-primary);
  font-weight: bold;
  letter-spacing: 1px;
}

.npc-toggle {
  background: transparent;
  border: none;
  color: var(--c-border);
  cursor: pointer;
  padding: 2px 4px;
  font-size: 13px;
  transition: color 0.2s ease;

  &:hover {
    color: var(--c-primary);
  }
}

.npc-body {
  padding: 12px;
}

.npc-name {
  font-size: 17px;
  font-weight: bold;
  color: var(--c-primary);
  letter-spacing: 1px;
  margin-bottom: 8px;
  text-shadow: 0 0 10px rgba(0, 229, 255, 0.35);
}

.npc-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 10px;
}

.meta-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  font-size: 11px;
  border: 1px solid var(--c-border);
  border-radius: 12px;
  background: var(--c-surface);

  i {
    color: var(--c-warn);
    width: 1em;
  }

  em {
    font-style: normal;
    opacity: 0.55;
  }

  &.body {
    i {
      color: var(--c-primary);
    }

    &.body-good i {
      color: #4cd964;
    }

    &.body-warn i {
      color: var(--c-warn);
    }

    &.body-bad {
      color: var(--c-accent);
      border-color: var(--c-accent);

      i {
        color: var(--c-accent);
      }
    }
  }
}

.npc-field {
  display: flex;
  gap: 10px;
  padding: 6px 0;
  border-top: 1px dashed var(--c-border);

  &:last-child {
    border-bottom: none;
  }

  &.action {
    .npc-text {
      color: var(--c-warn);
    }
  }
}

.npc-label {
  flex-shrink: 0;
  width: 4.5em;
  font-size: 11px;
  color: var(--c-primary);
  opacity: 0.75;
  padding-top: 1px;
}

.npc-text {
  flex: 1;
  margin: 0;
  font-size: 12px;
  color: var(--c-text);
  white-space: pre-wrap;
  word-break: break-word;
}

.npc-empty {
  font-size: 12px;
  color: var(--c-border);
  text-align: center;
  padding: 8px 0;

  i {
    margin-right: 6px;
  }
}

.npc-collapse-enter-active,
.npc-collapse-leave-active {
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.npc-collapse-enter-from,
.npc-collapse-leave-to {
  opacity: 0;
  transform: translateY(-6px);
}
