
.panel {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.block-title {
  font-size: 12px;
  color: var(--c-primary);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 3px;
  margin-bottom: 8px;
  letter-spacing: 1px;
}

.keel,
.layer {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  padding: 2px 0;
}

.keel-name,
.layer-name {
  width: 8.5em;
  color: var(--c-text);
  opacity: 0.85;
}

.keel-val,
.layer-val {
  width: 3em;
  text-align: right;
  font-weight: bold;
}

.bar {
  flex: 1;
  height: 8px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 1px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: currentColor;
  transition: width 0.4s ease;
}

.keel-fill {
  color: var(--c-warn);
  background: var(--c-warn);
}

.state-building {
  color: var(--c-primary);
  background: currentColor;
}

.state-done {
  color: #4cd964;
  background: currentColor;
}

.state-none {
  color: var(--c-border);
  background: currentColor;
}

.layer-val.state-building {
  color: var(--c-primary);
}

.layer-val.state-done {
  color: #4cd964;
}

.layer-val.state-none {
  color: var(--c-border);
}

.inf-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.inf-layer {
  display: flex;
  gap: 8px;
  align-items: flex-start;
}

.inf-warn {
  padding: 3px 6px;
  border: 1px solid var(--c-accent);
  border-radius: 4px;
  background-color: rgba(255, 77, 77, 0.06);
}

.inf-total {
  flex-shrink: 0;
  font-size: 10px;
  color: var(--c-border);
  padding-top: 1px;

  &.total-drift {
    color: var(--c-accent);
    font-weight: bold;
  }
}

.inf-layer-name {
  width: 6.5em;
  font-size: 11px;
  color: var(--c-primary);
  flex-shrink: 0;
  padding-top: 2px;
}

.inf-factions {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 4px 10px;
}

.inf {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--c-text);
  opacity: 0.85;
}

.inf-val {
  font-weight: bold;
  color: var(--c-warn);
}

.inf-name.lead,
.inf-val.lead {
  color: var(--c-accent);
  font-weight: bold;
}

.empty-hint {
  font-size: 12px;
  color: var(--c-border);
}
