
.panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.relation {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  padding: 4px 0;
}

.rel-name {
  width: 4.5em;
  font-weight: bold;
  color: var(--c-text);
}

.rel-bar {
  flex: 1;
  height: 8px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 1px;
  overflow: hidden;
}

.rel-fill {
  height: 100%;
  transition: width 0.4s ease;
}

.tier-high {
  color: var(--c-accent);
  background: var(--c-accent);
}

.tier-mid {
  color: #ff7a7a;
  background: #ff7a7a;
}

.tier-normal {
  color: var(--c-warn);
  background: var(--c-warn);
}

.tier-low {
  color: var(--c-primary);
  background: var(--c-primary);
}

.tier-zero {
  color: var(--c-border);
  background: var(--c-border);
}

.rel-val {
  width: 3em;
  text-align: right;
  font-weight: bold;
}

.rel-fill.tier-high,
.rel-fill.tier-mid,
.rel-fill.tier-normal,
.rel-fill.tier-low,
.rel-fill.tier-zero {
  background: currentColor;
}

.rel-tier {
  width: 2.5em;
  font-size: 11px;
  opacity: 0.8;
}

.empty-hint {
  font-size: 12px;
  color: var(--c-border);
}
